      "id": "a1-huebsch",
      "layout": "standardStudy",
      "translation": "pen • søt",
      "explanation": [
        "Hovedpoeng: hübsch er adjektivet «pen, søt» – om utseende, klær, hus og ting som er fine å se på. Det er mildere enn schön (vakker).",
        "Foran et substantiv bøyes hübsch som et vanlig adjektiv: ein hübsches Kleid, eine hübsche Frau, hübsche Blumen. Komparativ: hübscher, superlativ: am hübschesten.",
        "I dagligtale kan ganz hübsch også bety «ganske mye, veldig»: Das war ganz hübsch teuer."
      ],
      "examples": [
        {
          "de": "Sie ist ein hübsches Mädchen.",
          "lv": "Hun er en pen jente."
        },
        {
          "de": "Das Kleid ist wirklich hübsch.",
          "lv": "Kjolen er virkelig pen."
        },
        {
          "de": "Was für ein hübsches Haus!",
          "lv": "For et pent hus!"
        },
        {
          "de": "Du siehst heute hübsch aus.",
          "lv": "Du ser pen ut i dag."
        }
      ],
      "comparison": [
        {
          "word": "schön",
          "meaning": "vakker",
          "example": "Das Wetter ist schön. – Været er vakkert."
        },
        {
          "word": "süß",
          "meaning": "søt (også om smak)",
          "example": "Das Baby ist süß. – Babyen er søt."
        },
        {
          "word": "schick",
          "meaning": "elegant, flott",
          "example": "Du siehst schick aus. – Du ser elegant ut."
        }
      ],
      "tip": [
        "Hübsch brukes som et mildt kompliment, schön som et sterkere.",
        "Legg til endelse når ordet står foran et substantiv: ein hübsches Kleid, men Das Kleid ist hübsch."
      ],
      "important": [
        "Om menn brukes hübsch sjeldnere; oftere sier man gut aussehend eller attraktiv.",
        "Hübsch er mye brukt i dagligtale, men er ikke det samme som schön – schön er mer generelt og sterkere."
      ],
