      "explanation": [
        "Hovedpoeng: kosten betyr «koste» om prisen en vare eller tjeneste har: Das kostet fünf Euro – det koster fem euro. Subjektet er en ting, ikke en person.",
        "Former: kostet, kostete, hat gekostet. Spørsmål om pris: Was kostet das? (Hva koster det?), Wie viel kostet der Pullover? I flertall: Die Schuhe kosten 60 Euro.",
        "Personen som må betale, står i akkusativ: Das kostet mich zehn Euro. I overført betydning kan kosten også bety «kreve» tid eller krefter: Das kostet viel Zeit."
      ],
      "examples": [
        {
          "de": "Das kostet fünf Euro.",
          "lv": "Det koster fem euro."
        },
        {
          "de": "Was kostet das?",
          "lv": "Hva koster det?"
        },
        {
          "de": "Wie viel kostet der Pullover?",
          "lv": "Hvor mye koster genseren?"
        },
        {
          "de": "Die Schuhe kosten sechzig Euro.",
          "lv": "Skoene koster seksti euro."
        },
        {
          "de": "Das kostet mich viel Zeit.",
          "lv": "Det koster meg mye tid."
        }
      ],
      "comparison": [
        {
          "word": "bezahlen",
          "meaning": "betale",
          "example": "Ich bezahle die Rechnung. – Jeg betaler regningen."
        },
        {
          "word": "zahlen",
          "meaning": "betale (om en person)",
          "example": "Wir zahlen bar. – Vi betaler kontant."
        },
        {
          "word": "kaufen",
          "meaning": "kjøpe",
          "example": "Ich kaufe ein Brot. – Jeg kjøper et brød."
        }
      ],
      "tip": [
        "Kosten – prisen på en ting, zahlen/bezahlen – en person betaler: Der Kaffee kostet drei Euro, ich bezahle ihn.",
        "Slik spør du om prisen: Was kostet…? eller Wie viel kostet…?"
      ],
      "important": [
        "Substantivet Kosten (flertall) betyr «kostnader»; kosten som verb betyr «koste».",
        "Kosten kan også bety «smake på» (Willst du die Suppe kosten?), men i hverdagen bruker man probieren."
      ],
