        "Forskjellen fra liegen: legen uttrykker en handling (hvor hen?), liegen en tilstand (hvor?): Ich lege das Buch auf den Tisch, men Das Buch liegt auf dem Tisch. Paret tilsvarer norsk legge – ligge."
