      "explanation": [
        "Hovedpoeng: das Mal er et intetkjønnssubstantiv – «gang» (en gang noe skjer): das erste Mal (første gang), jedes Mal (hver gang), beim nächsten Mal (neste gang).",
        "Etter et tall står Mal vanligvis i entall og skrives atskilt eller sammen: zwei Mal / zweimal (to ganger), drei Mal / dreimal. Flertall die Male brukes sjelden, for eksempel mehrere Male.",
        "Mal er også en partikkel i talespråket (med liten forbokstav): Komm mal her! – Kom hit, da! Det er en annen bruk, som myker opp en oppfordring."
      ],
      "examples": [
        {
          "de": "Das erste Mal war schwer.",
          "lv": "Første gang var vanskelig."
        },
        {
          "de": "Ich war schon zweimal in Berlin.",
          "lv": "Jeg har allerede vært i Berlin to ganger."
        },
        {
          "de": "Jedes Mal vergesse ich es.",
          "lv": "Hver gang glemmer jeg det."
        },
        {
          "de": "Beim nächsten Mal komme ich früher.",
          "lv": "Neste gang kommer jeg tidligere."
        },
        {
          "de": "Noch einmal, bitte!",
          "lv": "En gang til, takk!"
        }
      ],
      "comparison": [
        {
          "word": "einmal",
          "meaning": "én gang",
          "example": "Ich war einmal in Wien. – Jeg har vært i Wien én gang."
        },
        {
          "word": "mal",
          "meaning": "partikkel (myker opp)",
          "example": "Komm mal her! – Kom hit, da!"
        },
        {
          "word": "die Zeit",
          "meaning": "tid",
          "example": "Ich habe keine Zeit. – Jeg har ikke tid."
        }
      ],
      "tip": [
        "Nyttige forbindelser: zum ersten Mal (for første gang), diesmal (denne gangen), jedes Mal (hver gang).",
        "Antall ganger uttrykkes med -mal: einmal, zweimal, dreimal."
      ],
      "important": [
        "Das Mal betyr også «merke, flekk»: das Muttermal (føflekk), das Denkmal (minnesmerke).",
        "Etter et tall skrives sammensetningen med liten forbokstav: zweimal, ikke «Zweimal»."
      ],
