        "Flertall: die Männer (menn, med omlyd). Genitiv: des Mannes, dativ flertall: den Männern. I sammensetninger: Ehemann, Geschäftsmann (flertall Geschäftsleute).",
        "Forskjellen fra man: man (en, folk) er et pronomen og skrives med liten forbokstav og én n. Mennesket generelt heter der Mensch."
