        "Am Morgen (am = an dem) betyr «om morgenen». Om noe som gjentar seg, bruker man morgens (hver morgen / om morgenen, adverb): Ich stehe morgens um sechs auf.",
        "Forskjellen fra morgen: morgen (med liten forbokstav) betyr «i morgen», der Morgen betyr «morgen» (morgenstund). Norsk bruker samme ord, men tysk skiller med stor og liten forbokstav og med preposisjon."
