      "translation": "skulle • burde",
      "explanation": [
        "Hovedpoeng: sollen er et modalverb som uttrykker at noen (en annen person, en regel, legen) vil eller krever at noe skal skje. Former: ich soll, du sollst, er soll, wir sollen; preteritum sollte, perfektum hat gesollt (sammen med infinitiv — hat ... sollen).",
        "Det andre verbet står i infinitiv sist i setningen: Du sollst mehr Wasser trinken. Konjunktivformen sollte uttrykker et råd: Du solltest schlafen (du burde sove).",
        "I spørsmålet Soll ich ...? spør man om noen vil at jeg skal gjøre noe — på norsk «Skal jeg ...?»."
      ],
      "examples": [
        {
          "de": "Der Arzt sagt, ich soll mehr Wasser trinken.",
          "lv": "Legen sier at jeg skal drikke mer vann."
        },
        {
          "de": "Soll ich das Fenster öffnen?",
          "lv": "Skal jeg åpne vinduet?"
        },
        {
          "de": "Du solltest früher ins Bett gehen.",
          "lv": "Du burde legge deg tidligere."
        },
        {
          "de": "Wir sollen um acht Uhr da sein.",
          "lv": "Vi skal være der klokka åtte."
        }
      ],
      "comparison": [
        {
          "word": "müssen",
          "meaning": "måtte, være nødt til",
          "example": "Ich muss arbeiten. – Jeg må jobbe."
        },
        {
          "word": "dürfen",
          "meaning": "få lov til",
          "example": "Darf ich gehen? – Får jeg gå?"
        },
        {
          "word": "wollen",
          "meaning": "ville",
          "example": "Ich will schlafen. – Jeg vil sove."
        }
      ],
      "tip": [
        "Sollen brukes når kravet kommer fra en annen: Der Lehrer sagt, wir sollen lesen.",
        "Når du vil gi et råd, bruk sollte: Du solltest mehr schlafen."
      ],
      "important": [
        "Nicht sollen betyr vanligvis «skal ikke» eller «bør ikke»: Du sollst nicht lügen.",
        "Sollen er ikke det samme som müssen: müssen uttrykker nødvendighet, sollen — en annen persons vilje eller en regel."
      ],
